#!/usr/bin/env bash
set -u

# Evaluate() v0 — replay harness (verifier-set member; candidates may not
# modify the harness or the mutation generator they are scored by).
#
# Usage:
#   evaluate-candidate.sh --out CAND_DIR --split-date YYYY-MM-DD -- CLASSIFIER...
#
# The classifier contract: CLASSIFIER... RECEIPT_PATH, exit 0 = accept,
# nonzero = reject. The constant-admit baseline is `true`.
#
# Corpus: all genuine receipts found in the standard receipt surfaces, plus
# labeled mutants generated by mutate-receipts.sh. Receipts are split into a
# search slice (date in filename <= split date; freely inspectable while
# tuning a candidate) and a held-out slice (scored here, once).
#
# Output (under CAND_DIR):
#   corpus/        genuine copies + mutants + labels.tsv
#   traces/        raw per-case classifier stdout+stderr+exit, never edited
#   scores.json    per-class recall by slice + constant-admit baseline

TOOLS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ROOT="$(cd "$TOOLS_DIR/.." && pwd)"
MUTATE="$TOOLS_DIR/eval/mutate-receipts.sh"

usage() {
  printf 'usage: %s --out CAND_DIR [--split-date YYYY-MM-DD] -- CLASSIFIER...\n' \
    "$(basename "$0")" >&2
}

CAND_DIR=""
SPLIT_DATE="2026-05-31"
while [[ "$#" -gt 0 ]]; do
  case "$1" in
    --out) CAND_DIR="${2:-}"; shift 2 ;;
    --split-date) SPLIT_DATE="${2:-}"; shift 2 ;;
    --) shift; break ;;
    *) usage; exit 64 ;;
  esac
done

if [[ -z "$CAND_DIR" || "$#" -lt 1 ]]; then
  usage
  exit 64
fi

CLASSIFIER=("$@")
CORPUS="$CAND_DIR/corpus"
TRACES="$CAND_DIR/traces"
mkdir -p "$CORPUS" "$TRACES"
: > "$CORPUS/labels.tsv"

# --- Assemble genuine corpus ------------------------------------------------

genuine_files=()
while IFS= read -r f; do
  base="$(basename "$f")"
  case "$base" in
    INDEX.md|RECEIPT-INDEX-*) continue ;;
  esac
  genuine_files+=("$f")
done < <(
  find "$ROOT/imports/receipts" "$ROOT/receipts" "$ROOT/pralaya/receipts" \
       "$ROOT/cycles/boat-2026-05-17/receipts" \
       -maxdepth 1 -type f -name '*.md' 2>/dev/null | sort
)

for f in "${genuine_files[@]}"; do
  cp "$f" "$CORPUS/$(basename "$f")"
  printf '%s\tgenuine\tnone\n' "$(basename "$f")" >> "$CORPUS/labels.tsv"
done

# --- Generate mutants (deterministic) ---------------------------------------

# Fail closed: a missing or failing mutation generator silently emptied the
# negative corpus (rc 0, zero mutants, scores.json still written) — the
# checker would then be scored against nothing it must reject. Evidence
# with no rejection side is not evidence (BIDIR-4.4).
[[ -f "$MUTATE" ]] || {
  printf 'evaluate-candidate: mutation generator missing: %s\n' "$MUTATE" >&2
  exit 65
}
bash "$MUTATE" "$CORPUS" "${genuine_files[@]}" >/dev/null || {
  printf 'evaluate-candidate: mutation generator failed (negative corpus incomplete)\n' >&2
  exit 65
}

# --- Slice assignment by date in filename -----------------------------------

slice_of() {
  local name="$1"
  local date
  date="$(printf '%s\n' "$name" | grep -Eo '[0-9]{4}-[0-9]{2}-[0-9]{2}' | head -n 1)"
  if [[ -z "$date" || ! "$date" > "$SPLIT_DATE" ]]; then
    printf 'search\n'
  else
    printf 'heldout\n'
  fi
}

# --- Replay ------------------------------------------------------------------

n_genuine_search=0
n_genuine_ok_search=0
n_mutant_search=0
n_mutant_rejected_search=0
n_genuine_heldout=0
n_genuine_ok_heldout=0
n_mutant_heldout=0
n_mutant_rejected_heldout=0

inc_counter() {
  local counter="$1" slice="$2"
  case "$counter:$slice" in
    n_genuine:search) n_genuine_search=$((n_genuine_search + 1)) ;;
    n_genuine_ok:search) n_genuine_ok_search=$((n_genuine_ok_search + 1)) ;;
    n_mutant:search) n_mutant_search=$((n_mutant_search + 1)) ;;
    n_mutant_rejected:search) n_mutant_rejected_search=$((n_mutant_rejected_search + 1)) ;;
    n_genuine:heldout) n_genuine_heldout=$((n_genuine_heldout + 1)) ;;
    n_genuine_ok:heldout) n_genuine_ok_heldout=$((n_genuine_ok_heldout + 1)) ;;
    n_mutant:heldout) n_mutant_heldout=$((n_mutant_heldout + 1)) ;;
    n_mutant_rejected:heldout) n_mutant_rejected_heldout=$((n_mutant_rejected_heldout + 1)) ;;
    *) printf 'evaluate-candidate: unknown counter: %s %s\n' "$counter" "$slice" >&2; exit 70 ;;
  esac
}

counter_value() {
  local counter="$1" slice="$2"
  case "$counter:$slice" in
    n_genuine:search) printf '%s\n' "$n_genuine_search" ;;
    n_genuine_ok:search) printf '%s\n' "$n_genuine_ok_search" ;;
    n_mutant:search) printf '%s\n' "$n_mutant_search" ;;
    n_mutant_rejected:search) printf '%s\n' "$n_mutant_rejected_search" ;;
    n_genuine:heldout) printf '%s\n' "$n_genuine_heldout" ;;
    n_genuine_ok:heldout) printf '%s\n' "$n_genuine_ok_heldout" ;;
    n_mutant:heldout) printf '%s\n' "$n_mutant_heldout" ;;
    n_mutant_rejected:heldout) printf '%s\n' "$n_mutant_rejected_heldout" ;;
    *) printf 'evaluate-candidate: unknown counter: %s %s\n' "$counter" "$slice" >&2; exit 70 ;;
  esac
}

while IFS=$'\t' read -r name label mutation; do
  [[ -n "$name" ]] || continue
  slice="$(slice_of "$name")"
  trace="$TRACES/$name.trace"
  {
    printf '# case: %s\n# label: %s\n# mutation: %s\n# slice: %s\n# classifier: %s\n' \
      "$name" "$label" "$mutation" "$slice" "${CLASSIFIER[*]}"
    "${CLASSIFIER[@]}" "$CORPUS/$name" 2>&1
    printf '# exit: %s\n' "$?"
  } > "$trace"
  exit_code="$(awk -F': ' '/^# exit:/ { v = $2 } END { print v }' "$trace")"

  if [[ "$label" == "genuine" ]]; then
    inc_counter n_genuine "$slice"
    [[ "$exit_code" == "0" ]] && inc_counter n_genuine_ok "$slice"
  else
    inc_counter n_mutant "$slice"
    [[ "$exit_code" != "0" ]] && inc_counter n_mutant_rejected "$slice"
  fi
done < "$CORPUS/labels.tsv"

# --- Scores ------------------------------------------------------------------

ratio() {
  local num="$1" den="$2"
  if [[ "$den" -eq 0 ]]; then printf 'null'; else
    awk -v n="$num" -v d="$den" 'BEGIN { printf "%.4f", n / d }'
  fi
}

{
  printf '{\n'
  printf '  "evaluated_at": "%s",\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '  "classifier": "%s",\n' "${CLASSIFIER[*]}"
  printf '  "split_date": "%s",\n' "$SPLIT_DATE"
  printf '  "task": "shape-discrimination (genuine vs mutant)",\n'
  printf '  "slices": {\n'
  comma=""
  for s in search heldout; do
    n_genuine_value="$(counter_value n_genuine "$s")"
    n_genuine_ok_value="$(counter_value n_genuine_ok "$s")"
    n_mutant_value="$(counter_value n_mutant "$s")"
    n_mutant_rejected_value="$(counter_value n_mutant_rejected "$s")"
    printf '%s    "%s": {\n' "$comma" "$s"
    printf '      "genuine": %s,\n' "$n_genuine_value"
    printf '      "mutants": %s,\n' "$n_mutant_value"
    printf '      "admit_recall": %s,\n' "$(ratio "$n_genuine_ok_value" "$n_genuine_value")"
    printf '      "deny_recall": %s\n' "$(ratio "$n_mutant_rejected_value" "$n_mutant_value")"
    printf '    }'
    comma=$',\n'
  done
  printf '\n  },\n'
  printf '  "baseline_constant_admit": { "admit_recall": 1.0, "deny_recall": 0.0 }\n'
  printf '}\n'
} > "$CAND_DIR/scores.json"

bash "$TOOLS_DIR/eval/attest.sh" write "$CAND_DIR/scores.json" "${BASH_SOURCE[0]}" "$TRACES" \
  || printf 'evaluate-candidate: WARNING: attestation failed; evidence is unattested\n' >&2

printf 'evaluate-candidate: wrote %s\n' "$CAND_DIR/scores.json"
cat "$CAND_DIR/scores.json"
